const tz = 'Europe/Lisbon';
const now = $now.setZone(tz);
let manual = false; try { manual = $('Test run').isExecuted; } catch (e) {}

const target = (now.weekday === 7 && now.hour >= 18) || manual ? now : now.minus({ weeks: 1 });
const S = {
  tz, week: target.toFormat("kkkk-'W'WW"), start: target.startOf('week').toISO(), end: target.endOf('week').toISO(),
  nextStart: target.startOf('week').plus({ weeks: 1 }).toISO(), nextEnd: target.endOf('week').plus({ weeks: 1 }).toISO(),
  folder: '/vault/Weekly', dailyFolder: '/vault/Daily', readLaterFolder: '/vault/Read later', inboxNote: '/vault/Inbox.md', gmailLogFolder: '/vault/Gmail',
  appCache: '/home/node/.n8n',
  googleMcpUrl: 'http://mcp-google:8000/mcp',
  ollamaUrl: 'http://host.docker.internal:11434',
  model: 'qwen3.8:27b',
  manual,
};
S.file = `${S.folder}/${S.week} Review.md`;
const fs = require('fs');
if (!manual && fs.existsSync(S.file)) return [];
if (!manual && now.weekday !== 7 && now.weekday !== 1 && fs.existsSync(S.file)) return [];
return [{ json: S }];

const fs = require('fs');
const S = $input.first().json;

const helpers = this.helpers;
let sid = null; let nextId = 0;
const parseBody = (body) => {
  if (Buffer.isBuffer(body)) body = body.toString('utf8');
  if (typeof body !== 'string') return body || {};
  const t = body.trim();
  if (t.startsWith('{')) return JSON.parse(t);
  const datas = t.split('\n').filter(l => l.startsWith('data:')).map(l => l.slice(5).trim());
  for (const d of datas.reverse()) { try { const j = JSON.parse(d); if (j.result || j.error) return j; } catch (e) {} }
  return {};
};
async function rpc(method, params, notify = false) {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' };
  if (sid) headers['mcp-session-id'] = sid;
  const msg = notify ? { jsonrpc: '2.0', method, params } : { jsonrpc: '2.0', id: ++nextId, method, params };
  const res = await helpers.httpRequest({ method: 'POST', url: S.googleMcpUrl, headers, body: JSON.stringify(msg),
    json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 120000 });
  const h = res.headers || {};
  sid = sid || h['mcp-session-id'] || h['Mcp-Session-Id'];
  if (notify) return null;
  const j = parseBody(res.body);
  if (j.error) throw new Error(j.error.message || JSON.stringify(j.error));
  return j.result;
}
async function mcpInit() {
  await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'n8n-gmail-organizer', version: '1' } });
  await rpc('notifications/initialized', {}, true);
}
async function tool(name, args) {
  const r = await rpc('tools/call', { name, arguments: args });
  const text = (r?.content || []).map(c => c.text || '').join('\n').trim();
  if (/ACTION REQUIRED|Authentication Needed/i.test(text)) throw new Error('Google sign-in needed (see README: Google sign-in link)');
  if (r?.isError) throw new Error(text.slice(0, 400));
  return text;
}

const t0 = Date.parse(S.start), t1 = Date.parse(S.end);
const inWeek = (t) => { const x = typeof t === 'number' ? t : Date.parse(t); return x >= t0 && x <= t1; };
const read = (f) => { try { return JSON.parse(fs.readFileSync(`${S.appCache}/${f}`, 'utf8')); } catch (e) { return null; } };
const W = { errors: [] };

W.days = [];
try {
  for (const f of fs.readdirSync(S.dailyFolder).filter(f => /^\d{4}-\d{2}-\d{2} Briefing\.md$/.test(f)).sort()) {
    const d = f.slice(0, 10); if (!inWeek(Date.parse(d + 'T12:00:00'))) continue;
    const t = fs.readFileSync(`${S.dailyFolder}/${f}`, 'utf8');
    const h = (t.split('### Highlights')[1] || '').split('\n### ')[0].trim();
    W.days.push({ date: d, highlights: h.slice(0, 1500) });
  }
} catch (e) { W.errors.push('daily notes: ' + e.message); }

try {
  await mcpInit();
  W.tasks = (await tool('list_tasks', { task_list_id: '@default', show_completed: true, show_hidden: true, max_results: 100 })).slice(0, 6000);
  W.nextWeek = (await tool('get_events', { calendar_id: 'primary', time_min: S.nextStart, time_max: S.nextEnd, max_results: 30 })).slice(0, 4000);
} catch (e) { W.errors.push('google: ' + e.message); }

const gh = read('mailapp-github.json');
W.github = (gh?.repos || []).map(r => ({ repo: r.repo, commits: (r.commits || []).filter(c => inWeek(c.at)), closed: (r.closedThisWeek || []).filter(c => inWeek(c.at)),
  openIssues: (r.issues || []).length, openPrs: (r.prs || []).length, ci: (r.runs || []).filter(w => inWeek(w.at)).reduce((m, w) => (m[w.conclusion || w.status] = (m[w.conclusion || w.status] || 0) + 1, m), {}) }));
const mail = read('mailapp-cache.json');
W.jobs = (mail?.jobs || []).filter(j => inWeek(j.date)).sort((a, b) => b.score - a.score).slice(0, 10);
W.jobsTotal = (mail?.jobs || []).filter(j => inWeek(j.date)).length;
W.needsMe = Object.values(mail?.meta || {}).filter(m => m.needs && inWeek(m.date)).map(m => `${m.fromName}: ${m.subject}`).slice(0, 15);
const vul = read('mailapp-vulns.json');
const ws = S.start.slice(0, 10), we = S.end.slice(0, 10);
W.kev = (vul?.kev || []).filter(k => k.added >= ws && k.added <= we).map(k => ({ id: k.id, what: `${k.vendor} ${k.product} – ${k.name}`, ransomware: k.ransomware }));
W.watch = Object.values(vul?.cves || {}).filter(x => x.watch?.length && inWeek(x.published)).map(x => ({ id: x.id, cvss: x.cvss, watch: x.watch, kev: x.kev }));
const yt = read('mailapp-youtube.json');
W.youtube = (yt?.videos || []).filter(v => inWeek(v.t) && v.verdict === 'watch').map(v => ({ title: v.title, channel: v.channel, link: v.link, why: v.why }));

try {
  const inbox = fs.existsSync(S.inboxNote) ? fs.readFileSync(S.inboxNote, 'utf8') : '';
  W.readSaved = fs.readdirSync(S.readLaterFolder).filter(f => f.endsWith('.md')).filter(f => { const t = fs.readFileSync(`${S.readLaterFolder}/${f}`, 'utf8'); const m = t.match(/^saved:\s*(.+)$/m); return m && inWeek(m[1].trim()); }).map(f => f.slice(0, -3));
  W.readUnread = (inbox.match(/^- \[ \] \[\[Read later\/[^\]|]+/gm) || []).map(l => l.replace(/^- \[ \] \[\[Read later\//, ''));
} catch (e) { W.readSaved = []; W.readUnread = []; }

try { W.gmail = fs.readFileSync(`${S.gmailLogFolder}/${S.week} Organizer.md`, 'utf8').split('## Undo')[0].slice(0, 1500); } catch (e) { W.gmail = ''; }
return [{ json: { ...S, W } }];

const fs = require('fs');
const S = $input.first().json; const W = S.W;
const data = `[Daily highlights]\n${W.days.map(d => `${d.date}:\n${d.highlights}`).join('\n\n') || 'none'}
[Google Tasks, raw, includes completed]\n${W.tasks || 'unavailable'}
[Next week's calendar, raw]\n${W.nextWeek || 'unavailable'}
[GitHub]\n${W.github.map(r => `${r.repo}: ${r.commits.length} commits (${r.commits.map(c => c.msg).join('; ').slice(0, 800)}), closed: ${r.closed.map(c => '#' + c.n + ' ' + c.title).join('; ') || 'none'}, ${r.openIssues} open issues, CI: ${JSON.stringify(r.ci)}`).join('\n') || 'no data'}
[Emails that needed me] ${W.needsMe.join('; ') || 'none'}
[Job matches this week] ${W.jobsTotal} total; best: ${W.jobs.slice(0, 5).map(j => `${j.role} @ ${j.company} (${j.score})`).join('; ') || 'none'}
[Security] new KEV: ${W.kev.map(k => k.id + ' ' + k.what).join('; ').slice(0, 1500) || 'none'}; my stack: ${W.watch.map(x => x.id + ' ' + x.watch.join('/')).join('; ') || 'none'}
[Read later] saved ${W.readSaved.length}, unread in total ${W.readUnread.length}`;
let ai = '';
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: `${S.ollamaUrl}/api/chat`, json: true, timeout: 600000,
    body: { model: S.model, stream: false, think: false, keep_alive: '2m', options: { num_ctx: 32768, temperature: 0.3 },
      messages: [{ role: 'user', content: `Write my weekly review for ${S.week} in English Markdown, using ONLY the data below. Never invent anything.
Sections, exactly:
## The week in short
One short paragraph.
## Done
Bullets: tasks completed this week (only ones the data shows as completed), GitHub progress, other wins.
## Still open
Bullets: open tasks, open issues, unanswered things that needed me.
## Next week
Bullets: what's on the calendar, then 3 concrete focus suggestions based on the data (e.g. which GitHub issue to tackle, which job to apply for, read-later backlog).

${data}` }] } });
  ai = (r.message?.content || '').trim();
} catch (e) { ai = `_AI summary unavailable: ${e.message}_`; }
const L = ['---', `week: ${S.week}`, 'tags: [weekly-review]', '---', '', `# Weekly review · ${S.week}`, '', ai, ''];
for (const r of W.github) {
  L.push(`### GitHub · [${r.repo}](https://github.com/${r.repo})`, `${r.commits.length} commits · ${r.closed.length} closed · ${r.openIssues} open issues · ${r.openPrs} open PRs · CI: ${Object.entries(r.ci).map(([k, v]) => `${v} ${k}`).join(', ') || 'no runs'}`);
  for (const c of r.closed) L.push(`- ✓ [#${c.n} ${c.title}](${c.url})`);
  L.push('');
}
if (W.jobs.length) { L.push(`### Best job matches (${W.jobsTotal} this week)`); for (const j of W.jobs) L.push(`- **${j.score}** [${j.role}](${j.url}) · ${j.company} · ${j.location} · ${j.mode}`); L.push(''); }
if (W.kev.length || W.watch.length) {
  L.push(`### Security this week`, `${W.kev.length} new actively exploited (KEV)`);
  for (const k of W.kev.slice(0, 15)) L.push(`- [${k.id}](https://nvd.nist.gov/vuln/detail/${k.id}) ${k.what}${k.ransomware ? ' · ransomware' : ''}`);
  for (const x of W.watch) L.push(`- **Your stack** [${x.id}](https://nvd.nist.gov/vuln/detail/${x.id}) CVSS ${x.cvss ?? '?'} · ${x.watch.join(', ')}`);
  L.push('');
}
if (W.youtube.length) { L.push('### Worth watching'); for (const v of W.youtube) L.push(`- [${v.title}](${v.link}) · ${v.channel}${v.why ? ' · ' + v.why : ''}`); L.push(''); }
L.push(`### Read later`, `Saved this week: ${W.readSaved.length} · unread: ${W.readUnread.length}`);
for (const n of W.readUnread.slice(0, 10)) L.push(`- [ ] [[Read later/${n}]]`);
L.push('');
if (W.days.length) L.push('### Daily notes', W.days.map(d => `[[Daily/${d.date} Briefing|${d.date}]]`).join(' · '), '');
if (W.errors.length) L.push('<small>Problems: ' + W.errors.join(' | ') + '</small>', '');
L.push('---', `_Generated ${$now.setZone(S.tz).toFormat('ccc d LLL HH:mm')} by n8n + ${S.model}._`);
fs.mkdirSync(S.folder, { recursive: true });
fs.writeFileSync(S.file, L.join('\n'), 'utf8');
return [{ json: { written: S.file.replace('/vault', 'Vault') } }];
